//! Merkle roots for every small tree over three distinct transaction ids.
//!
//! Each level hashes adjacent pairs with double SHA256. An odd level duplicates
//! its last hash before that hashing, and that duplicate is not itself a
//! mutation. A mutation is an adjacent pair that was already equal before the
//! duplicate. The three-leaf tree `123` and the four-leaf tree `1233` have the
//! same root. Only the four-leaf tree is mutated.

use blvm_consensus::mining::{calculate_merkle_root_from_tx_ids, compute_merkle_root_and_mutated};
use sha2::{Digest, Sha256};

fn leaf(symbol: u8) -> [u8; 32] {
    let mut out = [0u8; 32];
    out[0] = symbol;
    out[31] = 0xA0 + symbol - 1;
    out
}

fn leaves(pattern: &str) -> Vec<[u8; 32]> {
    pattern.bytes().map(|byte| leaf(byte - b'0')).collect()
}

fn sha256d(data: &[u8]) -> [u8; 32] {
    let first = Sha256::digest(data);
    let second = Sha256::digest(first);
    let mut out = [0u8; 32];
    out.copy_from_slice(&second);
    out
}

#[test]
fn every_small_tree_matches_the_pair_hash_and_the_mutation_flag() {
    let one = leaf(1);
    let (root, mutated) = compute_merkle_root_and_mutated(&[one]).unwrap();
    assert_eq!(root, one);
    assert!(!mutated);
    let mut pair = [0u8; 64];
    pair[..32].copy_from_slice(&one);
    pair[32..].copy_from_slice(&one);
    let (root, mutated) = compute_merkle_root_and_mutated(&[one, one]).unwrap();
    assert!(mutated);
    assert_eq!(root, sha256d(&pair));

    for (i, &(pattern, root_hex, mutated)) in ROWS.iter().enumerate() {
        let ids = leaves(pattern);
        let (root, flag) = compute_merkle_root_and_mutated(&ids).unwrap();
        assert_eq!(hex::encode(root), root_hex, "row {i} {pattern}");
        assert_eq!(flag, mutated, "row {i} {pattern} mutation");
        let accepted = calculate_merkle_root_from_tx_ids(&ids);
        if mutated {
            assert!(accepted.is_err(), "row {i} {pattern} must be rejected");
        } else {
            assert_eq!(accepted.unwrap(), root, "row {i} {pattern} accepted root");
        }
    }
}

#[test]
fn an_empty_transaction_list_has_no_merkle_root() {
    assert!(compute_merkle_root_and_mutated(&[]).is_err());
    assert!(calculate_merkle_root_from_tx_ids(&[]).is_err());
}

#[test]
fn duplicating_the_last_of_three_leaves_keeps_the_root_and_sets_the_flag() {
    let (odd, odd_flag) = compute_merkle_root_and_mutated(&leaves("123")).unwrap();
    let (even, even_flag) = compute_merkle_root_and_mutated(&leaves("1233")).unwrap();
    assert_eq!(odd, even);
    assert!(!odd_flag);
    assert!(even_flag);
}

